    "type": "function",
    "function": {
      "name": "slowSeizBckgModel_TenSeconds",
      "description": "Coarse 10-second montage classifier for the interval [start, end]. Each returned window has probabilities for background (bckg), slow waves (slow), and seizure (seiz). The interval is split into consecutive 10-second epochs; shorter remainders are dropped. High seiz means epileptic activity is likely in that 10-second window but is not channel-localized. Follow up with 1-second tools to name channels and finer times.",
      "constraints": "",
      "parameters": {
        "type": "object",
        "properties": {
          "start": {
            "type": "int",
            "description": "Start time in seconds."
          },
          "end": {
            "type": "int",
            "description": "End time in seconds. Should be at least 10 seconds after start."
          }
        },
        "required": [
          "start",
          "end"
        ]
      },
      "returns": {
        "type": "List[Dict]",
        "description": "One dict per 10-second epoch: duration plus Prob={bckg, slow, seiz}. These scores are independent of eyemMuscleModel_OneSecond."
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "compute_amplitude",
      "description": "need end - start <= 60. Compute amplitude features (mean absolute, RMS, peak values) of specified EEG channels in a given time window.",
      "constraints": "",
      "parameters": {
        "type": "object",
        "properties": {
          "name": {
            "type": "List[str]",
            "description": "List of channel names to analyze, e.g., ['FP1-F7', 'F7-T3']"
          },
          "start": {
            "type": "int",
            "description": "Start time in seconds."
          },
          "end": {
            "type": "int",
            "description": "End time in seconds."
          }
